CREATE TABLE IF NOT EXISTS docs (id TEXT PRIMARY KEY, body TEXT, rev INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, updated INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS limits (key TEXT NOT NULL, hour INTEGER NOT NULL, n INTEGER NOT NULL, PRIMARY KEY (key, hour));
CREATE TABLE IF NOT EXISTS inbox (id TEXT PRIMARY KEY, acct TEXT NOT NULL, dest TEXT NOT NULL, at INTEGER NOT NULL, kind TEXT NOT NULL, body TEXT NOT NULL, src TEXT NOT NULL DEFAULT '');
CREATE INDEX IF NOT EXISTS inbox_acct ON inbox (acct);
CREATE TABLE IF NOT EXISTS households (id TEXT PRIMARY KEY, body TEXT, rev INTEGER NOT NULL DEFAULT 0, created INTEGER NOT NULL, updated INTEGER NOT NULL, owner TEXT NOT NULL, invite TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS members (acct TEXT PRIMARY KEY, house TEXT NOT NULL, id TEXT NOT NULL, name TEXT NOT NULL DEFAULT '', joined INTEGER NOT NULL, seen INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS members_house ON members (house);
